(()=>{const e=document.querySelector("#weatherForm"),t=e.querySelector('input[name="city"]'),r=(e.querySelector('button[name="submit-button"]'),document.querySelector("#weather-data"));e.addEventListener("submit",async e=>{e.preventDefault();const n=t.value.trim();if(n)try{const e=await fetch(`https://api.openweathermap.org/data/2.5/weather?q=${n}&appid=8967388ef15aab5dc6624ae602ea61c9&units=metric&lang=ua`),t=await e.json();if(!e.ok)throw new Error(t.message||"City not found");!function(e){r.classList.remove("hidden"),console.log(e),r.querySelector("#weather-city").innerText=e.name,r.querySelector("#weather-description").innerText=e.weather[0].description,r.querySelector("#weather-temperature").innerText=`Температура: ${Math.round(e.main.temp)}°C`,r.querySelector("#weather-feels-like").innerText=`Відчувається як: ${Math.round(e.main.feels_like)}°C`,r.querySelector("#weather-humidity").innerText=`Вологість: ${e.main.humidity}%`,r.querySelector("#weather-wind").innerText=`Вітер: ${e.wind.speed} м/с`,r.querySelector("#weather-icon").setAttribute("src",`https://openweathermap.org/img/wn/${e.weather[0].icon}@2x.png`),r.querySelector("#weather-icon").setAttribute("alt",e.weather[0].description)}(t)}catch(e){console.error(e),alert(e.message)}else alert("Enter city name")})})();